    CONSTRAINT ck_term__confidentiality_duration_years CHECK (confidentiality_duration_years >= 0),
    CONSTRAINT ck_term__intellectual_property_ownership CHECK (intellectual_property_ownership IN ('client', 'agency', 'joint', 'work_for_hire', 'licensed')),
    CONSTRAINT ck_term__liability_cap_amount CHECK (liability_cap_amount >= 0),
    CONSTRAINT ck_term__liability_cap_currency CHECK (liability_cap_currency ~ '^[A-Z]{3}$'),
    CONSTRAINT ck_term__payment_method CHECK (payment_method IN ('wire_transfer', 'ach', 'check', 'credit_card', 'electronic_funds_transfer')),
    CONSTRAINT ck_term__payment_term_days CHECK (payment_term_days >= 0),
    CONSTRAINT ck_term__renewal_notice_days CHECK (renewal_notice_days >= 0),
    CONSTRAINT ck_term__risk_level CHECK (risk_level IN ('low', 'medium', 'high', 'critical')),
    CONSTRAINT ck_term__termination_notice_days CHECK (termination_notice_days >= 0)
);
